## Why This Is Asked
Tests understanding of async patterns, concurrency control, error handling, and closure-based state management - critical for production frontend systems.

## Expected Answer
Strong candidates will discuss: queue management with closures, Promise.allSettled vs Promise.all, handling partial failures, progress tracking, and cleanup mechanisms.

## Code Example
```javascript
function createUploadQueue(maxConcurrent = 3) {
  let activeUploads = 0;
  const queue = [];

  return {
    async upload(file) {
      return new Promise((resolve, reject) => {
        queue.push({ file, resolve, reject });
        processQueue();
      });
    },

    async uploadAll(files) {
      const results = await Promise.allSettled(
        files.map(file => this.upload(file))
      );

      const successful = results
        .filter(r => r.status === 'fulfilled')
        .map(r => r.value);

      const failed = results
        .filter(r => r.status === 'rejected')
        .map(r => r.reason);

      return { successful, failed };
    }
  };

  async function processQueue() {
    if (activeUploads >= maxConcurrent || queue.length === 0) return;

    activeUploads++;
    const { file, resolve, reject } = queue.shift();

    try {
      const result = await uploadFile(file);
      resolve(result);
    } catch (error) {
      reject(error);
    } finally {
      activeUploads--;
      processQueue();
    }
  }
}

async function uploadFile(file) {
  const formData = new FormData();
  formData.append('file', file);

  const response = await fetch('/api/upload', {
    method: 'POST',
    body: formData,
    timeout: 30000
  });

  if (!response.ok) {
    throw new Error(`Upload failed: ${response.statusText}`);
  }

  return await response.json();
}
```

## Error Handling Scenarios
1. **Network timeouts**: Implement retry logic with exponential backoff
2. **File size limits**: Pre-validate files before queuing
3. **Server errors**: Use Promise.allSettled to continue processing other files
4. **Memory leaks**: Clear resolved promises and implement cleanup
5. **Concurrent limits**: Adjust maxConcurrent based on network conditions

This question evaluates the ability to architect a real-time analytics UI with strict tenant isolation, efficient data handling, and React optimization techniques.

**Key Concepts**
- useSyncExternalStore for subscribing to external data streams
- Memoized selectors keyed by multiple dimensions (tenantId, metricId, timeWindow)
- Per-tenant data scoping with proper cleanup on tenant switch
- Real-time rendering with virtualization for large datasets
- Interactive zoom/pan handling with debouncing

**Code Sketches**

```javascript
// Stream wrapper
function createTenantStream(tenantId, metricId) {
  let subscribers = new Set();
  let currentData = [];
  let ws = null;

  const connect = () => {
    ws = new WebSocket(`/api/tenants/${tenantId}/metrics/${metricId}`);
    ws.onmessage = (e) => {
      currentData = [...currentData, JSON.parse(e.data)];
      subscribers.forEach(fn => fn(currentData));
    };
  };

  return {
    subscribe(fn) {
      subscribers.add(fn);
      if (!ws) connect();
      return () => subscribers.delete(fn);
    },
    getSnapshot() { return currentData; }
  };
}

// Memoized selector
function createMetricSelector(tenantId, metricId, timeWindow) {
  return useMemo(() => (data) => {
    const filtered = data.filter(d => 
      d.timestamp >= Date.now() - timeWindow
    );
    return downsample(filtered, 5000);
  }, [tenantId, metricId, timeWindow]);
}

// LineChart with virtualization
const LineChart = React.memo(function LineChart({ data, width, height }) {
  const canvasRef = useRef(null);
  return <canvas ref={canvasRef} width={width} height={height} />;
});

// Panel wiring
function PerTenantAnalyticsPanel({ tenantId, metricId, timeWindow }) {
  const theme = useContext(ThemeContext);
  const stream = useMemo(
    () => createTenantStream(tenantId, metricId),
    [tenantId, metricId]
  );
  const data = useSyncExternalStore(stream.subscribe, stream.getSnapshot);
  const selectMetric = createMetricSelector(tenantId, metricId, timeWindow);
  const series = selectMetric(data);

  useEffect(() => {
    return () => { /* cleanup zoom/pan state */ };
  }, [tenantId]);

  return <LineChart data={series} theme={theme} />;
}
```

